import {safeUrl,filterTools,progress} from './core.mjs';
const $=s=>document.querySelector(s), main=$('#main'), KEY='difference-hub-v1';
const base={tools:[],favorites:[],answers:{},plan:''};let state;try{state={...base,...JSON.parse(localStorage.getItem(KEY)||'{}')};if(!Array.isArray(state.tools)||!Array.isArray(state.favorites)||typeof state.answers!=='object'||!state.answers)throw Error();state.tools=state.tools.filter(t=>t&&typeof t.title==='string'&&typeof t.description==='string'&&safeUrl(t.url));state.plan=typeof state.plan==='string'?state.plan:''}catch{state={...base}}
let category='전체',query='',timer;const categories=['전체','수업 준비','수업 활동','교실 환경','자료 모음'];
const builtin={id:'classroom',title:'함께하는 교실 체크리스트',description:'우리 교실의 참여 장벽을 살펴보고, 모두가 함께 배우기 위한 작은 실천을 계획해요.',category:'교실 환경',url:'#checklist'};
const groups=[['이동과 공간',['교실의 이동 통로와 출입구에 장애물이 없는지 살폈어요.','누구나 사용할 수 있도록 좌석과 활동 공간을 유연하게 배치했어요.','조용히 쉬거나 감각 자극을 줄일 수 있는 공간을 안내했어요.']],['정보와 소통',['수업 안내를 말뿐 아니라 글·그림 등 여러 방식으로 제공해요.','영상에는 자막을, 그림에는 내용을 설명하는 말을 함께 제공해요.','질문에 답할 충분한 시간과 다양한 의사 표현 방법을 제공해요.']],['수업과 참여',['활동에 참여하는 방식과 결과물을 표현하는 방법을 선택할 수 있어요.','개인에게 필요한 지원을 추측하지 않고 본인의 의견을 물어요.','짝·모둠 활동에서 모든 학생에게 의미 있는 역할이 있어요.']],['존중하는 교실 문화',['장애를 동정이나 극복의 대상으로만 설명하지 않아요.','도움이 필요해 보일 때 먼저 의사를 묻고 선택을 존중해요.','차별적 표현이 들리면 멈추고 존중하는 표현을 함께 찾아요.']]];
const checks=groups.flatMap(([group,items],g)=>items.map((text,i)=>({id:g+'-'+i,text,group})));
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{notify('저장 공간을 사용할 수 없어요. 백업 파일을 내려받아 주세요.');return false}}
const art=(small=false)=>'<svg viewBox="0 0 320 270" fill="none" aria-hidden="true"><circle cx="179" cy="143" r="110" fill="#d8e4bc"/><path d="M33 235c38-14 82-18 130-12 48-17 97-14 139 8v21H33z" fill="#a9bd88"/><rect x="102" y="67" width="124" height="160" rx="8" fill="#fffdf4" transform="rotate(9 102 67)"/><rect x="78" y="64" width="125" height="158" rx="8" fill="#f9faf1" transform="rotate(-8 78 64)"/><rect x="104" y="51" width="67" height="23" rx="6" fill="#607d50" transform="rotate(-8 104 51)"/><path d="m102 100 5 5 9-13m-10 41 5 5 9-13m-10 41 5 5 9-13" stroke="#60854c" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><path d="m130 98 44-6m-40 38 44-6m-39 38 44-6" stroke="#c4ceb6" stroke-width="5" stroke-linecap="round"/><path d="M247 234V124m0 59c-40 0-39-39-39-39 38 0 39 39 39 39zm0-24c0-36 35-40 35-40 0 36-35 40-35 40z" stroke="#557847" stroke-width="5" stroke-linejoin="round" fill="#829d64"/><path d="M227 219h39l-7 33h-24z" fill="#c77b52"/><circle cx="57" cy="116" r="5" fill="#c2a56d"/><path d="m253 65 0 18m-9-9h18" stroke="#9bab76" stroke-width="3" stroke-linecap="round"/><circle cx="275" cy="197" r="4" fill="#c5a56b"/></svg>';
function header(title,sub,tag='TEACHER’S TOOLBOX',action=''){return '<div class="heading-row"><div><div class="eyebrow">'+tag+'</div><h1>'+title+'</h1><p>'+sub+'</p></div>'+action+'</div>'}
function home(favorites=false){main.innerHTML=header(favorites?'나의 즐겨찾기':'모두의 배움을 잇는 도구함',favorites?'자주 쓰는 도구를 한곳에서 만나보세요.':'장애이해 교육을 위한 작은 도구들, 선생님의 수업에 함께합니다.','TEACHER’S TOOLBOX','<button class="secondary" data-add>＋ 프로그램 추가</button>')+(favorites?'':'<section class="hero"><div class="hero-copy"><span class="pill">함께 배우는 교실의 시작</span><h2>다름을 이해하는 시간,<br><strong>함께하는 교실로 이어지도록.</strong></h2><p>거창한 준비 없이, 오늘 수업에서 시작하는 작은 변화.<br>선생님의 실천을 돕는 도구를 만나보세요.</p><a class="primary" href="#checklist">첫 번째 도구 시작하기 <span aria-hidden="true">↗</span></a></div><div class="hero-art">'+art()+'</div></section><div class="stats"><div class="stat"><div class="stat-icon" aria-hidden="true">▦</div><div><span>사용 가능한 도구</span><strong>'+(state.tools.length+1)+'<small>개</small></strong></div></div><div class="stat"><div class="stat-icon" aria-hidden="true">☆</div><div><span>나의 즐겨찾기</span><strong>'+state.favorites.length+'<small>개</small></strong></div></div><div class="stat"><div class="stat-icon" aria-hidden="true">☑</div><div><span>교실 점검 진행</span><strong>'+progress(state.answers,12).done+'<small>/ 12</small></strong></div></div></div>')+'<section aria-labelledby="tools-heading"><div class="section-head"><h2 id="tools-heading">'+(favorites?'즐겨찾는 도구':'수업에 마음을 더하는 도구')+'</h2><small>로그인 없이, 가볍게 시작하세요</small></div><div class="toolbar"><div class="tabs" aria-label="도구 분류">'+categories.map(c=>'<button class="tab '+(c===category?'selected':'')+'" data-category="'+c+'" aria-pressed="'+(c===category)+'">'+c+'</button>').join('')+'</div><label class="search" style="margin:0"><span class="sr-only" style="position:absolute;clip:rect(0,0,0,0)">도구 검색</span><input type="search" id="search" placeholder="필요한 도구를 찾아보세요" value="'+escape(query)+'"></label></div><div class="cards" id="cards"></div></section><div class="note-strip"><span aria-hidden="true">✳</span><p><strong>다름은 틀림이 아닌, 또 하나의 배움입니다.</strong>개인의 어려움보다 함께 바꿀 수 있는 환경을 먼저 살펴보세요.</p></div>';renderCards(favorites);$('#search').addEventListener('input',e=>{query=e.target.value;renderCards(favorites)})}
function renderCards(favorites){const tools=filterTools([builtin,...state.tools],query,category,state.favorites,favorites);$('#cards').innerHTML=tools.map(t=>'<article class="tool-card"><div class="card-visual">'+art(true)+'<button class="bookmark" data-fav="'+escape(t.id)+'" aria-label="'+escape(t.title)+' 즐겨찾기" aria-pressed="'+state.favorites.includes(t.id)+'">'+(state.favorites.includes(t.id)?'★':'☆')+'</button></div><div class="card-body"><div class="card-meta"><span class="badge">'+escape(t.category)+'</span><span>'+(t.id==='classroom'?'약 5분 · 교사용':'내가 추가한 도구')+'</span></div><h3>'+escape(t.title)+'</h3><p>'+escape(t.description)+'</p></div><div class="card-footer"><span>'+(t.id==='classroom'?'브라우저에서 바로 사용':'외부 웹앱')+'</span><a class="open-link" href="'+escape(t.url)+'" '+(t.id==='classroom'?'':'target="_blank" rel="noopener noreferrer"')+'>도구 열기 <span aria-hidden="true">↗</span></a>'+(t.id==='classroom'?'':'<button class="delete" data-delete="'+escape(t.id)+'">삭제</button>')+'</div></article>').join('')+(!tools.length?'<div class="empty">'+(favorites?'즐겨찾는 도구가 없어요. 별 버튼으로 도구를 담아보세요.':'검색 결과가 없어요. 다른 검색어나 분류를 선택해 보세요.')+'</div>':'')+(!favorites&&!query&&category==='전체'?'<div class="add-card"><span class="add-circle" aria-hidden="true">＋</span><strong>다음 배움의 도구를 기다려요</strong><p>직접 만든 프로그램을 추가하고<br>나만의 교육 도구함을 채워보세요.</p><button class="secondary" data-add>새 프로그램 연결하기 ↗</button></div>':'')}
function checklist(){main.innerHTML='<a href="#home" class="back">← 도구함으로 돌아가기</a>'+header('함께하는 교실 체크리스트','우리 교실의 참여 장벽을 살피고, 오늘 바꿀 수 있는 한 가지를 찾아보세요.','FIRST TOOL · INCLUSIVE CLASSROOM','<button class="secondary" id="print">인쇄 / PDF 저장 ↗</button>')+'<div class="app-layout"><section><div class="panel"><h2>모두가 참여할 수 있는 교실인가요?</h2><p>실천하고 있는 항목을 체크하세요. 점수로 교실을 평가하기보다, 다음 실천을 찾는 데 활용해 주세요.</p>'+groups.map(([name,items],g)=>'<fieldset class="check-group"><legend>'+String(g+1).padStart(2,'0')+' · '+name+'</legend>'+items.map((text,i)=>'<label class="check-row"><input type="checkbox" data-check="'+g+'-'+i+'" '+(state.answers[g+'-'+i]?'checked':'')+'><span>'+text+'</span></label>').join('')+'</fieldset>').join('')+'</div><div class="panel"><h2>오늘의 작은 실천</h2><p>누구의 부족함이 아닌, 함께 바꿀 수 있는 환경과 행동을 적어보세요. 학생 이름이나 개인 정보는 입력하지 마세요.</p><label for="plan">이번 주에 실천할 한 가지</label><textarea id="plan" maxlength="2000" placeholder="예: 다음 수업 안내를 글과 그림으로도 준비하기">'+escape(state.plan)+'</textarea><span class="saving" id="save-status">입력하면 현재 브라우저에 자동 저장됩니다.</span></div></section><aside class="app-summary"><div class="panel"><div class="eyebrow">OUR NEXT STEP</div><h2 style="margin-top:12px">함께하는 실천 현황</h2><div class="progress-number" id="progress-number"></div><div class="progress-track"><div class="progress-fill" id="progress-fill"></div></div><p id="progress-label" role="status"></p><div class="action-stack"><button class="primary" id="download-plan">실천 기록 내려받기 ↓</button><button class="secondary" id="reset-checks">점검 다시 시작하기</button></div></div><div class="panel"><h2>다음에 살펴볼 것</h2><div id="next-checks"></div><p style="margin-top:16px">필요한 지원은 사람마다 달라요. 당사자의 의견과 선택을 먼저 들어주세요.</p></div></aside></div>';updateProgress();$('#plan').addEventListener('input',e=>{state.plan=e.target.value;$('#save-status').textContent=save()?'현재 브라우저에 저장했어요.':'저장하지 못했어요. 파일로 내려받아 주세요.'});$('#print').onclick=()=>window.print();$('#download-plan').onclick=()=>download('함께하는-교실-실천기록.txt','함께하는 교실 체크리스트\n\n'+checks.map(c=>(state.answers[c.id]?'[완료] ':'[다음 실천] ')+c.text).join('\n')+'\n\n이번 주 실천\n'+state.plan,'text/plain;charset=utf-8');$('#reset-checks').onclick=()=>{if(confirm('체크 표시와 실천 메모를 모두 초기화할까요?')){state.answers={};state.plan='';save();checklist();notify('새 점검을 시작합니다.')}}}
function updateProgress(){const p=progress(state.answers,12);$('#progress-number').innerHTML=p.done+'<small> / '+p.total+'</small>';$('#progress-fill').style.width=p.percent+'%';$('#progress-label').textContent=p.percent+'% 실천 중 · 작은 변화가 쌓이고 있어요.';const next=checks.filter(c=>!state.answers[c.id]).slice(0,3);$('#next-checks').innerHTML=next.length?next.map(c=>'<div class="plan-item">'+c.text+'</div>').join(''):'<p>모든 항목을 살펴봤어요! 학생의 의견을 듣고 교실을 계속 점검해 보세요.</p>'}
function download(name,data,type='application/json'){const u=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function guide(){main.innerHTML=header('작은 도구, 함께 쓰는 방법','선생님의 수업에 맞게 도구함을 채워보세요.','ABOUT THIS WORKSPACE')+'<div class="guide-grid"><section class="panel"><h2>01. 살펴보고, 시작하기</h2><p>도구 카드의 ‘도구 열기’를 누르면 바로 시작할 수 있어요. 첫 번째 도구는 별도 가입 없이 브라우저 안에서 작동합니다.</p><ol><li>교실 체크리스트를 살펴보세요.</li><li>실천하고 있는 항목을 체크하세요.</li><li>다음 실천을 적고 기록을 인쇄하세요.</li></ol></section><section class="panel"><h2>02. 나만의 도구함 만들기</h2><p>별 버튼으로 자주 쓰는 도구를 모으고, ‘프로그램 추가’로 앞으로 만든 웹앱을 연결하세요. 추가한 도구는 현재 브라우저에서만 보입니다.</p><button class="secondary" data-add>＋ 프로그램 추가</button></section><section class="panel"><h2>03. 기록을 보관하는 방법</h2><p>즐겨찾기, 프로그램 목록, 점검 기록은 현재 기기의 브라우저에 저장됩니다. 브라우저 데이터를 지우면 함께 삭제돼요. 기기를 옮길 때는 백업 파일을 사용하세요.</p><div class="storage-tools"><button class="primary" id="backup">전체 기록 백업 ↓</button><button class="secondary" id="restore">백업 불러오기 ↑</button><input type="file" id="restore-file" accept=".json,application/json" hidden></div><p style="margin-top:13px">불러오기는 현재 도구함과 기록을 교체합니다.</p></section><section class="panel"><h2>04. 이해에서 참여로</h2><p>이 도구는 장애 진단이나 학생 평가를 위한 도구가 아닙니다. 학생의 특성을 단정하지 않고, 수업과 환경의 참여 장벽을 함께 살피기 위한 교사 성찰 도구입니다.</p><p>개인마다 필요한 지원과 선호하는 표현이 다를 수 있어요. 당사자의 선택을 존중하고 학생 개인 정보는 기록하지 마세요.</p></section></div>';$('#backup').onclick=()=>download('다름을잇다-백업.json',JSON.stringify({version:1,...state},null,2));$('#restore').onclick=()=>$('#restore-file').click();$('#restore-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>1000000)throw Error();const d=JSON.parse(await f.text());if(d.version!==1||!Array.isArray(d.tools)||!Array.isArray(d.favorites)||typeof d.answers!=='object'||!d.answers||typeof d.plan!=='string'||d.plan.length>2000||d.tools.length>200||!d.tools.every(t=>typeof t.id==='string'&&typeof t.title==='string'&&t.title.length<=40&&typeof t.description==='string'&&t.description.length<=160&&safeUrl(t.url)&&categories.includes(t.category))||!d.favorites.every(x=>typeof x==='string')||Object.entries(d.answers).some(([k,v])=>!checks.some(c=>c.id===k)||typeof v!=='boolean'))throw Error();if(confirm('현재 기록을 백업 파일의 내용으로 교체할까요?')){state={tools:d.tools,favorites:d.favorites,answers:d.answers,plan:d.plan};save();render();notify('백업 기록을 불러왔어요.')}}catch{notify('올바른 다름을 잇다 백업 파일을 선택해 주세요.')}e.target.value=''}}
function render(){const route=location.hash.slice(1)||'home';document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===route);if(a.dataset.nav===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#fav-count').textContent=state.favorites.length;if(route==='checklist')checklist();else if(route==='guide')guide();else home(route==='favorites')}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){$('#tool-form').reset();$('#form-error').textContent='';$('#tool-dialog').showModal()}const fav=e.target.closest('[data-fav]');if(fav){const id=fav.dataset.fav;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();render();notify(state.favorites.includes(id)?'즐겨찾기에 담았어요.':'즐겨찾기에서 해제했어요.')}const tab=e.target.closest('[data-category]');if(tab){category=tab.dataset.category;home(location.hash==='#favorites')}const del=e.target.closest('[data-delete]');if(del&&confirm('이 프로그램을 내 도구함에서 삭제할까요?')){state.tools=state.tools.filter(t=>t.id!==del.dataset.delete);state.favorites=state.favorites.filter(x=>x!==del.dataset.delete);save();render();notify('프로그램 연결을 삭제했어요.')}});
document.addEventListener('change',e=>{if(e.target.matches('[data-check]')){state.answers[e.target.dataset.check]=e.target.checked;save();updateProgress()}});
$('#close-dialog').onclick=()=>$('#tool-dialog').close();$('#tool-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const title=f.get('title').trim(),description=f.get('description').trim(),url=f.get('url').trim();if(!title||!description||!safeUrl(url)){$('#form-error').textContent='이름과 소개, 올바른 공개 HTTPS 주소를 입력해 주세요.';return}state.tools.push({id:crypto.randomUUID(),title,description,url,category:f.get('category')});save();$('#tool-dialog').close();query='';category='전체';if(location.hash!=='#home')location.hash='home';else render();notify('새 프로그램을 도구함에 연결했어요.')};
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);main.focus()});render();
